package ae.build;

import java.io.ByteArrayOutputStream;
import java.io.DataOutputStream;
import java.io.IOException;
import java.nio.BufferUnderflowException;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.TreeMap;
import java.util.zip.CRC32;

/**
 * Persistent memory of earlier builds: per rule key the value, its hash and the dependencies (with
 * the dependency value hashes seen when the rule last ran).
 *
 * <p>File layout (big endian): {@code "AEBS"} magic, version byte, int record count, records
 * (key, value, hash, int dep count, deps (key, hash)) with strings as int length + UTF-8, then a
 * CRC32 of everything before it. Records are written in key order, so equal stores give equal bytes.
 */
public final class Store {
    /** Magic (4) + version (1) + record count (4). */
    static final int HEADER_SIZE = 9;
    /** CRC32 trailer. */
    static final int FOOTER_SIZE = 4;

    private static final byte[] MAGIC = {'A', 'E', 'B', 'S'};
    private static final byte VERSION = 1;

    /** A dependency together with the hash of its value when the owner last ran. */
    record Dep(String key, String hash) { }

    /** Read-only view of one stored record. */
    public record RecordView(String value, String hash, List<Dep> deps) {
        public List<String> depKeys() {
            return deps.stream().map(Dep::key).toList();
        }
    }

    private final Map<String, RecordView> records = new TreeMap<>();

    public RecordView record(String key) {
        return records.get(key);
    }

    public Set<String> keys() {
        return Set.copyOf(records.keySet());
    }

    public int size() {
        return records.size();
    }

    void put(String key, RecordView rec) {
        records.put(key, rec);
    }

    boolean remove(String key) {
        return records.remove(key) != null;
    }

    /** Writes the store via a temp file in the same directory and an atomic move. */
    public void save(Path file) throws IOException {
        byte[] bytes = encode();
        Path dir = file.toAbsolutePath().getParent();
        Path tmp = Files.createTempFile(dir, ".store-", ".tmp");
        try {
            Files.write(tmp, bytes);
            try {
                Files.move(tmp, file, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
            } catch (AtomicMoveNotSupportedException e) {
                Files.move(tmp, file, StandardCopyOption.REPLACE_EXISTING);
            }
        } finally {
            Files.deleteIfExists(tmp);
        }
    }

    /** Loads and validates a store; throws {@link CorruptStoreException} for any damage. */
    public static Store load(Path file) throws IOException {
        return decode(Files.readAllBytes(file));
    }

    private byte[] encode() throws IOException {
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        DataOutputStream out = new DataOutputStream(bos);
        out.write(MAGIC);
        out.writeByte(VERSION);
        out.writeInt(records.size());
        for (Map.Entry<String, RecordView> e : records.entrySet()) {
            writeString(out, e.getKey());
            writeString(out, e.getValue().value());
            writeString(out, e.getValue().hash());
            out.writeInt(e.getValue().deps().size());
            for (Dep d : e.getValue().deps()) {
                writeString(out, d.key());
                writeString(out, d.hash());
            }
        }
        out.flush();
        return seal(bos.toByteArray());
    }

    /** Appends the CRC32 trailer to {@code body}. */
    static byte[] seal(byte[] body) {
        CRC32 crc = new CRC32();
        crc.update(body);
        return ByteBuffer.allocate(body.length + FOOTER_SIZE).put(body).putInt((int) crc.getValue()).array();
    }

    private static void writeString(DataOutputStream out, String s) throws IOException {
        byte[] b = s.getBytes(StandardCharsets.UTF_8);
        out.writeInt(b.length);
        out.write(b);
    }

    private static Store decode(byte[] bytes) throws CorruptStoreException {
        if (bytes.length < HEADER_SIZE + FOOTER_SIZE) {
            throw new CorruptStoreException("file too short: " + bytes.length);
        }
        CRC32 crc = new CRC32();
        crc.update(bytes, 0, bytes.length - FOOTER_SIZE);
        int stored = ByteBuffer.wrap(bytes, bytes.length - FOOTER_SIZE, FOOTER_SIZE).getInt();
        if (stored != (int) crc.getValue()) {
            throw new CorruptStoreException("checksum mismatch");
        }
        ByteBuffer buf = ByteBuffer.wrap(bytes, 0, bytes.length - FOOTER_SIZE);
        try {
            byte[] magic = new byte[MAGIC.length];
            buf.get(magic);
            if (!Arrays.equals(magic, MAGIC)) {
                throw new CorruptStoreException("bad magic");
            }
            if (buf.get() != VERSION) {
                throw new CorruptStoreException("unsupported version");
            }
            int count = buf.getInt();
            // every record needs at least 4 ints of length/count fields
            if (count < 0 || (long) count * 16 > buf.remaining()) {
                throw new CorruptStoreException("implausible record count " + count);
            }
            Store store = new Store();
            String previous = null;
            for (int i = 0; i < count; i++) {
                String key = readString(buf);
                if (previous != null && key.compareTo(previous) <= 0) {
                    throw new CorruptStoreException("keys not strictly ascending at " + key);
                }
                previous = key;
                String value = readString(buf);
                String hash = readString(buf);
                int deps = buf.getInt();
                if (deps < 0 || (long) deps * 8 > buf.remaining()) {
                    throw new CorruptStoreException("implausible dep count " + deps);
                }
                List<Dep> list = new ArrayList<>(deps);
                for (int d = 0; d < deps; d++) {
                    list.add(new Dep(readString(buf), readString(buf)));
                }
                store.records.put(key, new RecordView(value, hash, List.copyOf(list)));
            }
            if (buf.hasRemaining()) {
                throw new CorruptStoreException("trailing bytes: " + buf.remaining());
            }
            return store;
        } catch (BufferUnderflowException e) {
            throw new CorruptStoreException("truncated record");
        }
    }

    private static String readString(ByteBuffer buf) throws CorruptStoreException {
        int len = buf.getInt();
        if (len < 0 || len > buf.remaining()) {
            throw new CorruptStoreException("bad string length " + len);
        }
        byte[] b = new byte[len];
        buf.get(b);
        return new String(b, StandardCharsets.UTF_8);
    }

    @Override
    public String toString() {
        return "Store" + Objects.toString(records.keySet());
    }
}

package ae.build;

import java.util.Objects;

/** A key failed to build. {@link #key()} names the key whose own task (or lookup) failed. */
public class BuildException extends RuntimeException {
    private static final long serialVersionUID = 1L;

    private final String key;

    public BuildException(String key, String message, Throwable cause) {
        super(message, cause);
        this.key = Objects.requireNonNull(key);
    }

    /** The key that failed first (not the dependents that merely propagated the failure). */
    public String key() {
        return key;
    }
}

package ae.build;

/** A build rule body. Dependencies are discovered by calling {@link Context#need}. */
@FunctionalInterface
public interface Task {
    /**
     * Computes the value of the rule.
     *
     * @return a non-null value
     * @throws Exception any failure; it is wrapped in a {@link BuildException}
     */
    String run(Context ctx) throws Exception;
}

package ae.build;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Deque;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;

/**
 * Incremental build engine with dynamic dependencies and early cutoff.
 *
 * <p>A rule is rerun only if the stored record is missing or one of its recorded dependencies now has
 * a different value hash (checked in recorded order, stopping at the first difference). Not thread
 * safe: use one builder from one thread.
 */
public final class Builder {

    private final Store store;
    private final Map<String, String> inputs = new HashMap<>();
    private final Map<String, Task> rules = new HashMap<>();

    private List<String> lastExecuted = List.of();
    private List<String> lastReused = List.of();

    public Builder() {
        this(new Store());
    }

    public Builder(Store store) {
        this.store = Objects.requireNonNull(store);
    }

    public Store store() {
        return store;
    }

    /** Sets (or changes) a leaf input value. */
    public void input(String key, String value) {
        Objects.requireNonNull(key);
        Objects.requireNonNull(value);
        if (rules.containsKey(key)) {
            throw new IllegalArgumentException("key is a rule: " + key);
        }
        inputs.put(key, value);
    }

    /** Registers (or replaces) the rule for {@code key}. */
    public void rule(String key, Task task) {
        Objects.requireNonNull(key);
        Objects.requireNonNull(task);
        if (inputs.containsKey(key)) {
            throw new IllegalArgumentException("key is an input: " + key);
        }
        rules.put(key, task);
    }

    public String build(String key) {
        return build(List.of(Objects.requireNonNull(key))).get(0);
    }

    /** One run building all keys in order; work is shared between them. */
    public List<String> build(List<String> keys) {
        Run run = new Run();
        List<String> out = new ArrayList<>();
        try {
            for (String k : keys) {
                out.add(run.resolve(Objects.requireNonNull(k)).value);
            }
        } finally {
            lastExecuted = List.copyOf(run.executed);
            lastReused = List.copyOf(run.reused);
        }
        return out;
    }

    /** Rules that ran in the last run, in completion order. */
    public List<String> lastExecuted() {
        return lastExecuted;
    }

    /** Rules verified clean (not run) in the last run, in completion order. */
    public List<String> lastReused() {
        return lastReused;
    }

    /** Removes records not reachable from {@code roots} through recorded deps; returns how many. */
    public int prune(Collection<String> roots) {
        Set<String> live = new HashSet<>();
        Deque<String> todo = new ArrayDeque<>(roots);
        while (!todo.isEmpty()) {
            String k = todo.pop();
            Store.RecordView rec = store.record(k);
            if (rec != null && live.add(k)) {
                todo.addAll(rec.depKeys());
            }
        }
        int removed = 0;
        for (String k : store.keys()) {
            if (!live.contains(k) && store.remove(k)) {
                removed++;
            }
        }
        return removed;
    }

    static String hash(String value) {
        try {
            byte[] d = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(d.length * 2);
            for (byte b : d) {
                sb.append(Character.forDigit((b >> 4) & 0xf, 16)).append(Character.forDigit(b & 0xf, 16));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }

    /** Outcome of resolving one key within a run. */
    private record Resolved(String value, String hash) { }

    private final class Run {
        final Map<String, Resolved> done = new HashMap<>();
        final Map<String, BuildException> failed = new HashMap<>();
        final Deque<String> stack = new ArrayDeque<>();
        final Set<String> onStack = new HashSet<>();
        final List<String> executed = new ArrayList<>();
        final List<String> reused = new ArrayList<>();

        Resolved resolve(String key) {
            Resolved r = done.get(key);
            if (r != null) {
                return r;
            }
            BuildException f = failed.get(key);
            if (f != null) {
                throw f;
            }
            if (onStack.contains(key)) {
                List<String> path = new ArrayList<>();
                boolean in = false;
                // stack iterates from the most recent entry; collect oldest-first from the loop start
                List<String> oldestFirst = new ArrayList<>(stack);
                java.util.Collections.reverse(oldestFirst);
                for (String s : oldestFirst) {
                    in |= s.equals(key);
                    if (in) {
                        path.add(s);
                    }
                }
                path.add(key);
                throw new CycleException(path);
            }
            stack.push(key);
            onStack.add(key);
            try {
                r = compute(key);
                done.put(key, r);
                return r;
            } catch (BuildException e) {
                failed.putIfAbsent(key, e);
                throw e;
            } finally {
                stack.pop();
                onStack.remove(key);
            }
        }

        private Resolved compute(String key) {
            String in = inputs.get(key);
            if (in != null) {
                return new Resolved(in, hash(in));
            }
            Task task = rules.get(key);
            if (task == null) {
                throw new BuildException(key, "no rule or input for key: " + key, null);
            }
            Store.RecordView rec = store.record(key);
            if (rec != null && verified(rec)) {
                reused.add(key);
                return new Resolved(rec.value(), rec.hash());
            }
            return execute(key, task);
        }

        /** True if every recorded dep still has the recorded hash; a dep that fails counts as changed. */
        private boolean verified(Store.RecordView rec) {
            for (Store.Dep d : rec.deps()) {
                Resolved dep;
                try {
                    dep = resolve(d.key());
                } catch (BuildException e) {
                    return false;
                }
                if (!dep.hash.equals(d.hash())) {
                    return false;
                }
            }
            return true;
        }

        private Resolved execute(String key, Task task) {
            TaskContext ctx = new TaskContext();
            String value;
            try {
                value = task.run(ctx);
            } catch (BuildException e) {
                throw e;
            } catch (Exception e) {
                throw new BuildException(key, "task failed: " + key + ": " + e, e);
            } finally {
                ctx.open = false;
                executed.add(key);
            }
            if (value == null) {
                throw new BuildException(key, "task returned null: " + key, new IllegalStateException("null result"));
            }
            String h = hash(value);
            List<Store.Dep> deps = new ArrayList<>();
            ctx.needed.forEach((k, dh) -> deps.add(new Store.Dep(k, dh)));
            store.put(key, new Store.RecordView(value, h, List.copyOf(deps)));
            return new Resolved(value, h);
        }

        private final class TaskContext implements Context {
            final Map<String, String> needed = new LinkedHashMap<>();
            boolean open = true;

            @Override
            public String need(String key) {
                if (!open) {
                    throw new IllegalStateException("context used after its task finished");
                }
                Resolved r = resolve(Objects.requireNonNull(key));
                needed.putIfAbsent(key, r.hash);
                return r.value;
            }
        }
    }

}

package ae.build;

import java.util.List;

/** Dependencies form a cycle. {@link #path()} is e.g. {@code [a, b, c, a]}. */
public class CycleException extends BuildException {
    private static final long serialVersionUID = 1L;

    private final transient List<String> path;

    public CycleException(List<String> path) {
        super(path.get(0), "dependency cycle: " + String.join(" -> ", path), null);
        this.path = List.copyOf(path);
    }

    public List<String> path() {
        return path;
    }
}

package ae.build;

import java.io.IOException;

/** The persisted store failed validation (bad magic, checksum, length or structure). */
public class CorruptStoreException extends IOException {
    private static final long serialVersionUID = 1L;

    public CorruptStoreException(String message) {
        super(message);
    }
}

package ae.build;

/** Handle given to a running {@link Task}; only valid while the task runs. */
public interface Context {
    /**
     * Builds {@code key} (recursively) and returns its value. The key is recorded as a dependency
     * of the running task, once, in first-need order.
     *
     * @throws BuildException if the dependency fails (a task may catch it)
     * @throws IllegalStateException if the task already finished
     */
    String need(String key);
}

