package ae.build;

import static org.junit.jupiter.api.Assertions.*;

import java.util.ArrayList;
import java.util.List;
import org.junit.jupiter.api.Test;

class BuilderTest {

    /** Rule that concatenates the values of the given deps with '+' and counts its runs. */
    private static Task concat(String... deps) {
        return ctx -> {
            StringBuilder sb = new StringBuilder();
            for (String d : deps) {
                if (sb.length() > 0) {
                    sb.append('+');
                }
                sb.append(ctx.need(d));
            }
            return sb.toString();
        };
    }

    @Test
    void buildsDiamondAndRunsEachRuleOnce() {
        Builder b = new Builder();
        b.input("src", "x");
        b.rule("left", concat("src"));
        b.rule("right", concat("src"));
        b.rule("top", concat("left", "right"));
        assertEquals("x+x", b.build("top"));
        // completion order: deps before dependents, "left" before "right" (first-need order)
        assertEquals(List.of("left", "right", "top"), b.lastExecuted());
    }

    @Test
    void secondBuildWithoutChangesRunsNothing() {
        Builder b = new Builder();
        b.input("src", "x");
        b.rule("a", concat("src"));
        b.rule("b", concat("a"));
        b.build("b");
        assertEquals("x", b.build("b"));
        assertEquals(List.of(), b.lastExecuted());
        assertEquals(List.of("a", "b"), b.lastReused());
    }

    @Test
    void changedInputReruns_onlyAffectedRules() {
        Builder b = new Builder();
        b.input("p", "1");
        b.input("q", "2");
        b.rule("fromP", concat("p"));
        b.rule("fromQ", concat("q"));
        b.rule("all", concat("fromP", "fromQ"));
        assertEquals("1+2", b.build("all"));
        b.input("p", "9");
        assertEquals("9+2", b.build("all"));
        assertEquals(List.of("fromP", "all"), b.lastExecuted());
        assertEquals(List.of("fromQ"), b.lastReused());
    }

    @Test
    void earlyCutoffStopsPropagationWhenValueIsUnchanged() {
        Builder b = new Builder();
        b.input("n", "4");
        // parity: 4 and 6 both give "even"
        b.rule("parity", ctx -> Integer.parseInt(ctx.need("n")) % 2 == 0 ? "even" : "odd");
        b.rule("label", ctx -> "is " + ctx.need("parity"));
        assertEquals("is even", b.build("label"));
        b.input("n", "6");
        assertEquals("is even", b.build("label"));
        assertEquals(List.of("parity"), b.lastExecuted(), "label must be reused: parity's value did not change");
        assertEquals(List.of("label"), b.lastReused());
        b.input("n", "7");
        assertEquals("is odd", b.build("label"));
        assertEquals(List.of("parity", "label"), b.lastExecuted());
    }

    @Test
    void dynamicDependenciesAreRecordedFromWhatTheTaskActuallyNeeded() {
        Builder b = new Builder();
        b.input("flag", "a");
        b.input("a", "A1");
        b.input("b", "B1");
        b.rule("pick", ctx -> ctx.need(ctx.need("flag")));
        assertEquals("A1", b.build("pick"));

        b.input("b", "B2"); // pick never needed b
        assertEquals("A1", b.build("pick"));
        assertEquals(List.of(), b.lastExecuted());

        b.input("a", "A2");
        assertEquals("A2", b.build("pick"));
        assertEquals(List.of("pick"), b.lastExecuted());

        b.input("flag", "b"); // flips the dependency
        assertEquals("B2", b.build("pick"));
        b.input("a", "A3"); // no longer relevant
        assertEquals("B2", b.build("pick"));
        assertEquals(List.of(), b.lastExecuted());
        b.input("b", "B3");
        assertEquals("B3", b.build("pick"));
        assertEquals(List.of("pick"), b.lastExecuted());
    }

    @Test
    void verificationStopsAtFirstChangedDependency() {
        // "gate" needs "mode" first and then, only for mode=full, "heavy" (which must not be touched
        // while verifying after mode changed to "off": the stale record would need heavy).
        List<String> ran = new ArrayList<>();
        Builder b = new Builder();
        b.input("mode", "full");
        b.input("h", "H");
        b.rule("heavy", ctx -> {
            ran.add("heavy");
            return ctx.need("h");
        });
        b.rule("gate", ctx -> ctx.need("mode").equals("full") ? ctx.need("heavy") : "none");
        assertEquals("H", b.build("gate"));
        ran.clear();
        b.input("mode", "off");
        assertEquals("none", b.build("gate"));
        assertEquals(List.of("gate"), b.lastExecuted());
        assertEquals(List.of(), ran, "heavy was not needed by the new run");
    }

    @Test
    void duplicateNeedsAreRecordedOnceAndReturnSameValue() {
        Builder b = new Builder();
        b.input("s", "v");
        b.rule("twice", ctx -> ctx.need("s") + ctx.need("s"));
        assertEquals("vv", b.build("twice"));
        assertEquals(List.of("s"), b.store().record("twice").depKeys());
    }

    @Test
    void failingTaskWrapsCauseAndKeepsOldRecord() {
        Builder b = new Builder();
        b.input("n", "2");
        b.rule("inv", ctx -> String.valueOf(10 / Integer.parseInt(ctx.need("n"))));
        b.rule("msg", ctx -> "got " + ctx.need("inv"));
        b.rule("other", concat("n"));
        assertEquals("got 5", b.build("msg"));

        b.input("n", "0");
        BuildException e = assertThrows(BuildException.class, () -> b.build("msg"));
        assertEquals("inv", e.key());
        assertInstanceOf(ArithmeticException.class, e.getCause());
        assertEquals("5", b.store().record("inv").value(), "old record survives a failed rerun");

        // unrelated key still builds; fixing the input recovers
        assertEquals("0", b.build("other"));
        b.input("n", "5");
        assertEquals("got 2", b.build("msg"));
    }

    @Test
    void failureIsMemoisedWithinOneRunAndSharedByDependents() {
        int[] runs = {0};
        Builder b = new Builder();
        b.rule("bad", ctx -> {
            runs[0]++;
            throw new IllegalStateException("boom");
        });
        b.rule("a", concat("bad"));
        b.rule("b", concat("bad"));
        b.rule("top", ctx -> ctx.need("a") + ctx.need("b"));
        BuildException e = assertThrows(BuildException.class, () -> b.build("top"));
        assertEquals("bad", e.key());
        assertEquals(1, runs[0]);
        assertThrows(BuildException.class, () -> b.build("top"));
        assertEquals(2, runs[0], "a new run retries the failed rule");
    }

    @Test
    void taskCanCatchFailureOfDependency() {
        Builder b = new Builder();
        b.rule("bad", ctx -> {
            throw new IllegalStateException("boom");
        });
        b.rule("safe", ctx -> {
            try {
                return ctx.need("bad");
            } catch (BuildException e) {
                return "fallback:" + e.key();
            }
        });
        assertEquals("fallback:bad", b.build("safe"));
    }

    @Test
    void cycleIsReportedWithPath() {
        Builder b = new Builder();
        b.rule("a", concat("b"));
        b.rule("b", concat("c"));
        b.rule("c", concat("a"));
        CycleException e = assertThrows(CycleException.class, () -> b.build("a"));
        assertEquals(List.of("a", "b", "c", "a"), e.path());
        // the failure is reported against the key that closed the loop
        assertEquals("a", e.key());
    }

    @Test
    void selfCycleAndCycleReachedFromOutside() {
        Builder b = new Builder();
        b.rule("self", concat("self"));
        b.rule("entry", concat("x"));
        b.rule("x", concat("y"));
        b.rule("y", concat("x"));
        assertEquals(List.of("self", "self"), assertThrows(CycleException.class, () -> b.build("self")).path());
        assertEquals(List.of("x", "y", "x"), assertThrows(CycleException.class, () -> b.build("entry")).path());
    }

    @Test
    void unknownKeyAndMissingInputAreBuildExceptions() {
        Builder b = new Builder();
        b.rule("r", concat("nope"));
        BuildException e = assertThrows(BuildException.class, () -> b.build("r"));
        assertEquals("nope", e.key());
        assertThrows(BuildException.class, () -> b.build("nope"));
    }

    @Test
    void removedDependencyForcesRerunInsteadOfFailing() {
        Builder b = new Builder();
        b.input("old", "1");
        b.rule("r", concat("old"));
        assertEquals("1", b.build("r"));
        // a new Builder sharing the store, where "old" no longer exists and r changed shape
        Builder b2 = new Builder(b.store());
        b2.input("fresh", "2");
        b2.rule("r", concat("fresh"));
        assertEquals("2", b2.build("r"));
        assertEquals(List.of("r"), b2.lastExecuted());
    }

    @Test
    void keyCannotBeBothInputAndRule_andNullsRejected() {
        Builder b = new Builder();
        b.input("k", "v");
        assertThrows(IllegalArgumentException.class, () -> b.rule("k", concat("k")));
        b.rule("r", concat("k"));
        assertThrows(IllegalArgumentException.class, () -> b.input("r", "v"));
        assertThrows(NullPointerException.class, () -> b.input("z", null));
        assertThrows(NullPointerException.class, () -> b.rule("z", null));
        assertThrows(NullPointerException.class, () -> b.build((String) null));
    }

    @Test
    void nullResultIsAnError_andContextExpiresAfterTask() {
        Builder b = new Builder();
        b.rule("nul", ctx -> null);
        assertInstanceOf(IllegalStateException.class, assertThrows(BuildException.class, () -> b.build("nul")).getCause());

        Context[] leaked = new Context[1];
        b.input("s", "v");
        b.rule("leak", ctx -> {
            leaked[0] = ctx;
            return ctx.need("s");
        });
        b.build("leak");
        assertThrows(IllegalStateException.class, () -> leaked[0].need("s"));
    }

    @Test
    void pruneDropsUnreachableRecords() {
        Builder b = new Builder();
        b.input("i", "1");
        b.rule("keep", concat("i"));
        b.rule("deep", concat("keep"));
        b.rule("gone", concat("i"));
        b.build("deep");
        b.build("gone");
        assertEquals(1, b.prune(List.of("deep")));
        assertNull(b.store().record("gone"));
        assertNotNull(b.store().record("keep"));
        assertEquals(0, b.prune(List.of("deep")));
    }

    @Test
    void buildSeveralKeysInOneRunSharesWork() {
        Builder b = new Builder();
        b.input("i", "1");
        b.rule("shared", concat("i"));
        b.rule("a", concat("shared"));
        b.rule("c", concat("shared"));
        assertEquals(List.of("1", "1"), b.build(List.of("a", "c")));
        assertEquals(List.of("shared", "a", "c"), b.lastExecuted());
    }
}

package ae.build;

import static org.junit.jupiter.api.Assertions.*;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Stream;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class StoreTest {

    private static Builder sample(Store store) {
        Builder b = new Builder(store);
        b.input("a", "héllo ✓");
        b.input("b", "");
        b.rule("x", ctx -> ctx.need("a") + "|" + ctx.need("b"));
        b.rule("y", ctx -> ctx.need("x").toUpperCase(java.util.Locale.ROOT));
        return b;
    }

    @Test
    void roundTripLetsAFreshBuilderReuseEverything(@TempDir Path dir) throws IOException {
        Path file = dir.resolve("build.db");
        Builder first = sample(new Store());
        assertEquals("HÉLLO ✓|", first.build("y"));
        first.store().save(file);

        Builder second = sample(Store.load(file));
        assertEquals("HÉLLO ✓|", second.build("y"));
        assertEquals(List.of(), second.lastExecuted());
        assertEquals(List.of("x", "y"), second.lastReused());

        second.input("b", "!");
        assertEquals("HÉLLO ✓|!", second.build("y"));
        assertEquals(List.of("x", "y"), second.lastExecuted());
    }

    @Test
    void saveOverwritesAndLeavesNoTempFiles(@TempDir Path dir) throws IOException {
        Path file = dir.resolve("build.db");
        Builder b = sample(new Store());
        b.build("y");
        b.store().save(file);
        b.input("a", "other");
        b.build("y");
        b.store().save(file);
        Builder reloaded = sample(Store.load(file));
        reloaded.input("a", "other"); // sample() seeds the original input; restore the saved one
        assertEquals("OTHER|", reloaded.build("y"));
        assertEquals(List.of(), reloaded.lastExecuted(), "saved records match input 'other'");
        try (Stream<Path> s = Files.list(dir)) {
            assertEquals(List.of("build.db"), s.map(p -> p.getFileName().toString()).toList());
        }
    }

    @Test
    void bytesAreCanonicalRegardlessOfInsertionOrder(@TempDir Path dir) throws IOException {
        Builder one = sample(new Store());
        one.build("y");
        Builder two = sample(new Store());
        two.build("x");
        two.build("y");
        Path f1 = dir.resolve("1.db");
        Path f2 = dir.resolve("2.db");
        one.store().save(f1);
        two.store().save(f2);
        assertArrayEquals(Files.readAllBytes(f1), Files.readAllBytes(f2));
    }

    @Test
    void emptyStoreRoundTrips(@TempDir Path dir) throws IOException {
        Path file = dir.resolve("e.db");
        new Store().save(file);
        assertEquals(0, Store.load(file).size());
    }

    @Test
    void everyTruncationIsRejected(@TempDir Path dir) throws IOException {
        byte[] good = goodBytes(dir);
        for (int len = 0; len < good.length; len++) {
            Path f = dir.resolve("t" + len + ".db");
            Files.write(f, Arrays.copyOf(good, len));
            final int n = len;
            assertThrows(CorruptStoreException.class, () -> Store.load(f), "truncated to " + n);
        }
    }

    @Test
    void everySingleByteFlipIsRejected(@TempDir Path dir) throws IOException {
        byte[] good = goodBytes(dir);
        for (int i = 0; i < good.length; i++) {
            byte[] bad = good.clone();
            bad[i] ^= 0x40;
            Path f = dir.resolve("f" + i + ".db");
            Files.write(f, bad);
            final int at = i;
            assertThrows(CorruptStoreException.class, () -> Store.load(f), "flip at byte " + at);
        }
    }

    @Test
    void validChecksumButBrokenStructureIsRejected(@TempDir Path dir) throws IOException {
        // trailing garbage after a valid body, re-sealed with a correct CRC
        byte[] good = goodBytes(dir);
        byte[] body = Arrays.copyOf(good, good.length - Store.FOOTER_SIZE);
        byte[] extended = Arrays.copyOf(body, body.length + 3);
        Path f = dir.resolve("x.db");
        Files.write(f, Store.seal(extended));
        assertThrows(CorruptStoreException.class, () -> Store.load(f));

        // claim an absurd record count with a valid CRC
        byte[] huge = Arrays.copyOf(body, body.length);
        huge[Store.HEADER_SIZE - 4] = (byte) 0x7f; // high byte of the int count
        Files.write(f, Store.seal(huge));
        assertThrows(CorruptStoreException.class, () -> Store.load(f));
    }

    @Test
    void missingFileIsAnIoErrorNotCorruption(@TempDir Path dir) {
        IOException e = assertThrows(IOException.class, () -> Store.load(dir.resolve("nope.db")));
        assertFalse(e instanceof CorruptStoreException);
    }

    private static byte[] goodBytes(Path dir) throws IOException {
        Builder b = sample(new Store());
        b.build("y");
        Path f = dir.resolve("good.db");
        b.store().save(f);
        return Files.readAllBytes(f);
    }
}

package ae.build;

import static org.junit.jupiter.api.Assertions.*;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.Set;
import java.util.TreeMap;
import org.junit.jupiter.api.Test;

/**
 * Differential test: a random layered graph of rules with value-dependent (dynamic) deps is built
 * incrementally across many random input edits and compared to a from-scratch build every time.
 */
class RandomizedBuildTest {

    private static final int INPUTS = 6;
    private static final int RULES = 24;

    /** Describes the graph with plain data so two Builders can be wired identically. */
    private static final class Spec {
        final Map<String, String> inputs = new TreeMap<>();
        // rule r<i> may only need inputs or rules with smaller index => acyclic
        final List<List<String>> candidates = new ArrayList<>();
        final List<Integer> mod = new ArrayList<>();

        Spec(Random rnd) {
            for (int i = 0; i < INPUTS; i++) {
                inputs.put("in" + i, String.valueOf(rnd.nextInt(4)));
            }
            for (int r = 0; r < RULES; r++) {
                List<String> c = new ArrayList<>();
                int n = 2 + rnd.nextInt(3);
                for (int k = 0; k < n; k++) {
                    int pick = rnd.nextInt(INPUTS + r);
                    c.add(pick < INPUTS ? "in" + pick : "r" + (pick - INPUTS));
                }
                candidates.add(c);
                mod.add(2 + rnd.nextInt(3));
            }
        }

        /** r: needs candidate[0]; its value mod m picks which further candidate is needed (dynamic). */
        Builder wire(Map<String, String> currentInputs) {
            Builder b = new Builder();
            currentInputs.forEach(b::input);
            for (int r = 0; r < RULES; r++) {
                final List<String> c = candidates.get(r);
                final int m = mod.get(r);
                b.rule("r" + r, ctx -> {
                    String first = ctx.need(c.get(0));
                    int sel = 1 + Math.floorMod(first.hashCode(), c.size() - 1);
                    String second = ctx.need(c.get(sel));
                    // coarse output so early cutoff happens often
                    return String.valueOf(Math.floorMod((first + "/" + second).hashCode(), m));
                });
            }
            return b;
        }
    }

    @Test
    void incrementalEqualsFromScratchAndRunsMinimalWork() {
        for (long seed = 1; seed <= 25; seed++) {
            Random rnd = new Random(seed);
            Spec spec = new Spec(rnd);
            Map<String, String> inputs = new TreeMap<>(spec.inputs);
            Builder inc = spec.wire(inputs);
            List<String> targets = List.of("r" + (RULES - 1), "r" + (RULES - 2), "r" + (RULES / 2));

            // Inputs edited at any point so far. A rule unreached for a while may rerun on a stale
            // record, so the per-step set would be too strict; the cumulative set is sound.
            Set<String> everChanged = new HashSet<>();
            for (int step = 0; step < 30; step++) {
                String ctxMsg = "seed " + seed + " step " + step;
                Set<String> changed = new HashSet<>();
                int edits = rnd.nextInt(3); // 0 edits happens often: the no-op run
                for (int e = 0; e < edits; e++) {
                    String k = "in" + rnd.nextInt(INPUTS);
                    String v = String.valueOf(rnd.nextInt(4));
                    if (!v.equals(inputs.get(k))) {
                        changed.add(k);
                    }
                    inputs.put(k, v);
                    inc.input(k, v);
                }
                Set<String> hadRecord = new HashSet<>(inc.store().keys());
                everChanged.addAll(changed);
                List<String> got = inc.build(targets);

                Builder scratch = spec.wire(inputs);
                assertEquals(scratch.build(targets), got, ctxMsg);

                List<String> executed = inc.lastExecuted();
                assertEquals(new HashSet<>(executed).size(), executed.size(), "a rule ran twice: " + ctxMsg);
                assertTrue(executed.size() <= scratch.lastExecuted().size(), ctxMsg);
                if (changed.isEmpty() && step > 0) {
                    assertEquals(List.of(), executed, "nothing changed, nothing may run: " + ctxMsg);
                }
                // every executed rule has a recorded dependency chain down to a changed input
                // (the post-run records are the ones that ran, so check against the scratch graph)
                for (String rule : executed) {
                    // a rule with no earlier record (newly reached by a flipped dynamic dep) may run
                    // without any changed input below it
                    assertTrue(!hadRecord.contains(rule) || reaches(inc, rule, everChanged, new HashSet<>()),
                            rule + " ran without a changed input below it: " + ctxMsg);
                }
            }
        }
    }

    /** True when {@code key} transitively depends (via current records) on a changed input. */
    private static boolean reaches(Builder b, String key, Set<String> changed, Set<String> seen) {
        if (changed.contains(key)) {
            return true;
        }
        if (!seen.add(key)) {
            return false;
        }
        Store.RecordView rec = b.store().record(key);
        if (rec == null) {
            return false;
        }
        for (String d : rec.depKeys()) {
            if (reaches(b, d, changed, seen)) {
                return true;
            }
        }
        return false;
    }
}
